def transform(grid):
    # Collect isolated T tetrominoes and convert their four orientations to marker colors.
    h,w=len(grid),len(grid[0]); seen=set(); shapes=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=2 or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); pts=[]
        while stack:
          x,y=stack.pop(); pts.append((x,y))
          for a,b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
            if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
              seen.add((a,b)); stack.append((a,b))
        if len(pts)!=4: continue
        r0=min(x for x,y in pts); c0=min(y for x,y in pts)
        p={(x-r0,y-c0) for x,y in pts}
        if max(x for x,y in p)==1 and max(y for x,y in p)==2:
          d='up' if (0,1) in p else 'down'
        elif max(x for x,y in p)==2 and max(y for x,y in p)==1:
          d='left' if (1,0) in p else 'right'
        else: continue
        shapes.append((r0,c0,d))
    shapes.sort()
    out=[[0]*6 for _ in range(3)]
    # T pointing up maps to 3; pointing down maps to 1. Left/right remain 0.
    # Output rows list the two orientations, with three positions each.
    ups=sum(1 for _,_,d in shapes if d=='up')
    downs=sum(1 for _,_,d in shapes if d=='down')
    if ups: out[0][0]=3
    if downs: out[0][3]=1
    return out

